import { Database } from "bun:sqlite";
import { mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { drizzle } from "drizzle-orm/bun-sqlite";
import { migrate } from "drizzle-orm/bun-sqlite/migrator";
import { relations } from "./relations";

/** SQL migrations generated by `bun run db:generate`. */
export const migrationsFolder = join(import.meta.dir, "../../drizzle");

/**
 * Opens (or creates) the SQLite database and applies any pending migrations.
 * Pass ":memory:" for a throwaway database in tests. Tests also pass a copy of
 * `migrations` so they can add their own.
 */
export function openDatabase(path: string, migrations = migrationsFolder) {
  if (path !== ":memory:") mkdirSync(dirname(path), { recursive: true });

  const client = new Database(path, { create: true });
  client.exec("PRAGMA journal_mode = WAL");
  client.exec("PRAGMA busy_timeout = 5000");

  const db = drizzle({ client, relations });

  // Foreign keys must stay off while migrating, following SQLite's ALTER TABLE procedure
  // (https://www.sqlite.org/lang_altertable.html#otheralter).
  // To change a column, drizzle-kit rebuilds the table and drops the old one. With foreign keys
  // on, that DROP deletes every row first, and ON DELETE CASCADE empties the child tables.
  // The `PRAGMA foreign_keys=OFF` that drizzle-kit writes into migrations does nothing, because
  // Drizzle runs them inside a transaction, so we turn foreign keys off here, before it starts.
  // See https://github.com/drizzle-team/drizzle-orm/issues/5782.
  client.exec("PRAGMA foreign_keys = OFF");
  try {
    migrate(db, { migrationsFolder: migrations });
    const broken = client.query("PRAGMA foreign_key_check").all();
    if (broken.length > 0) {
      throw new Error(
        `Migrations left ${broken.length} row(s) pointing at missing parents: ${JSON.stringify(broken.slice(0, 5))}`,
      );
    }
  } catch (error) {
    client.close();
    throw error;
  }
  client.exec("PRAGMA foreign_keys = ON");

  return db;
}

export type Db = ReturnType<typeof openDatabase>;
